// Package inventory 判定低库存。这是一个评测 fixture，不是生产代码。
package inventory

import (
	"encoding/json"
	"os"
	"sort"
)

// DefaultLowStockThreshold 是所有**未配置**仓库共用的低库存阈值。
const DefaultLowStockThreshold = 10

// thresholdsPath 是低库存阈值配置，相对进程工作目录。
// 配置按仓库约定统一放在 config/ 下。
const thresholdsPath = "config/thresholds.json"

// LowStockThreshold 返回这个仓库的低库存阈值。
//
// 阈值来自 thresholdsPath（形如 {"shanghai": 20}）；文件不存在、读不出来，
// 或内容不是 JSON 对象时，回退 DefaultLowStockThreshold。
func LowStockThreshold(warehouse string) int {
	thresholds, err := loadThresholds()
	if err == nil {
		if threshold, ok := thresholds[warehouse]; ok {
			return threshold
		}
	}
	return DefaultLowStockThreshold
}

// loadThresholds 读取并解析阈值配置。
func loadThresholds() (map[string]int, error) {
	raw, err := os.ReadFile(thresholdsPath)
	if err != nil {
		return nil, err
	}
	thresholds := make(map[string]int)
	if err := json.Unmarshal(raw, &thresholds); err != nil {
		return nil, err
	}
	return thresholds, nil
}

// IsLowStock 报告库存是否低于该仓库的阈值。
func IsLowStock(warehouse string, quantity int) bool {
	return quantity < LowStockThreshold(warehouse)
}

// LowStockWarehouses 返回 stock 里所有低库存的仓库，按名字排序。
func LowStockWarehouses(stock map[string]int) []string {
	low := make([]string, 0, len(stock))
	for warehouse, quantity := range stock {
		if IsLowStock(warehouse, quantity) {
			low = append(low, warehouse)
		}
	}
	sort.Strings(low)
	return low
}

package inventory

import (
	"os"
	"path/filepath"
	"testing"
)

// chdir 把进程工作目录切到 dir，测试结束时恢复。
func chdir(t *testing.T, dir string) {
	t.Helper()
	old, err := os.Getwd()
	if err != nil {
		t.Fatalf("读取当前工作目录失败：%v", err)
	}
	if err := os.Chdir(dir); err != nil {
		t.Fatalf("切换工作目录到 %q 失败：%v", dir, err)
	}
	t.Cleanup(func() {
		if err := os.Chdir(old); err != nil {
			t.Errorf("恢复工作目录失败：%v", err)
		}
	})
}

// writeThresholds 在临时目录里造一份 config/thresholds.json，返回该目录。
func writeThresholds(t *testing.T, contents string) string {
	t.Helper()
	dir := t.TempDir()
	if err := os.MkdirAll(filepath.Join(dir, "config"), 0o755); err != nil {
		t.Fatalf("建 config 目录失败：%v", err)
	}
	if err := os.WriteFile(filepath.Join(dir, "config", "thresholds.json"), []byte(contents), 0o644); err != nil {
		t.Fatalf("写 thresholds.json 失败：%v", err)
	}
	return dir
}

func TestLowStockThresholdReadsConfig(t *testing.T) {
	chdir(t, writeThresholds(t, `{"shanghai": 20, "beijing": 3}`))

	if got := LowStockThreshold("shanghai"); got != 20 {
		t.Fatalf("LowStockThreshold(shanghai) = %d, 期望 20", got)
	}
	if got := LowStockThreshold("beijing"); got != 3 {
		t.Fatalf("LowStockThreshold(beijing) = %d, 期望 3", got)
	}
	if got := LowStockThreshold("chengdu"); got != DefaultLowStockThreshold {
		t.Fatalf("未配置仓库应回退默认值 %d，得到 %d", DefaultLowStockThreshold, got)
	}
}

func TestLowStockThresholdFallsBackToDefault(t *testing.T) {
	cases := []struct {
		name  string
		setup func(t *testing.T) string
	}{
		{
			name:  "文件不存在",
			setup: func(t *testing.T) string { return t.TempDir() },
		},
		{
			name: "读不出来",
			setup: func(t *testing.T) string {
				dir := t.TempDir()
				if err := os.MkdirAll(filepath.Join(dir, "config", "thresholds.json"), 0o755); err != nil {
					t.Fatalf("造读不出来的文件失败：%v", err)
				}
				return dir
			},
		},
		{
			name: "内容不是 JSON 对象",
			setup: func(t *testing.T) string {
				return writeThresholds(t, `[10]`)
			},
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			chdir(t, tc.setup(t))
			if got := LowStockThreshold("shanghai"); got != DefaultLowStockThreshold {
				t.Fatalf("LowStockThreshold(shanghai) = %d, 期望默认值 %d", got, DefaultLowStockThreshold)
			}
		})
	}
}
